use std::ffi::OsStr;
use std::path::{Component, Path, PathBuf};

use crate::error::Result;
use ignored_suffixes::IgnoredSuffixes;

use globset::{Candidate, GlobBuilder, GlobMatcher};

pub mod ignored_suffixes;

#[derive(Debug, Clone, Copy, PartialEq)]
#[non_exhaustive]
pub enum MappingTarget<'a> {
    /// For mapping a path to a specific syntax.
    MapTo(&'a str),

    /// For mapping a path (typically an extension-less file name) to an unknown
    /// syntax. This typically means later using the contents of the first line
    /// of the file to determine what syntax to use.
    MapToUnknown,

    /// For mapping a file extension (e.g. `*.conf`) to an unknown syntax. This
    /// typically means later using the contents of the first line of the file
    /// to determine what syntax to use. However, if a syntax handles a file
    /// name that happens to have the given file extension (e.g. `resolv.conf`),
    /// then that association will have higher precedence, and the mapping will
    /// be ignored.
    MapExtensionToUnknown,
}

#[derive(Debug, Clone, Default)]
pub struct SyntaxMapping<'a> {
    mappings: Vec<(GlobMatcher, MappingTarget<'a>)>,
    pub(crate) ignored_suffixes: IgnoredSuffixes<'a>,
}

impl<'a> SyntaxMapping<'a> {
    pub fn empty() -> SyntaxMapping<'a> {
        Default::default()
    }

    pub fn builtin() -> SyntaxMapping<'a> {
        let mut mapping = Self::empty();
        mapping.insert("*.h", MappingTarget::MapTo("C++")).unwrap();
        mapping
            .insert(".clang-format", MappingTarget::MapTo("YAML"))
            .unwrap();
        mapping.insert("*.fs", MappingTarget::MapTo("F#")).unwrap();
        mapping
            .insert("build", MappingTarget::MapToUnknown)
            .unwrap();
        mapping
            .insert("**/.ssh/config", MappingTarget::MapTo("SSH Config"))
            .unwrap();
        mapping
            .insert(
                "**/bat/config",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert(
                "/etc/profile",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert("*.pac", MappingTarget::MapTo("JavaScript (Babel)"))
            .unwrap();

        // See #2151, https://nmap.org/book/nse-language.html
        mapping
            .insert("*.nse", MappingTarget::MapTo("Lua"))
            .unwrap();

        // See #1008
        mapping
            .insert("rails", MappingTarget::MapToUnknown)
            .unwrap();

        // Nginx and Apache syntax files both want to style all ".conf" files
        // see #1131 and #1137
        mapping
            .insert("*.conf", MappingTarget::MapExtensionToUnknown)
            .unwrap();

        for glob in &[
            "/etc/nginx/**/*.conf",
            "/etc/nginx/sites-*/**/*",
            "nginx.conf",
            "mime.types",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("nginx")).unwrap();
        }

        for glob in &[
            "/etc/apache2/**/*.conf",
            "/etc/apache2/sites-*/**/*",
            "httpd.conf",
        ] {
            mapping
                .insert(glob, MappingTarget::MapTo("Apache Conf"))
                .unwrap();
        }

        for glob in &[
            "**/systemd/**/*.conf",
            "**/systemd/**/*.example",
            "*.automount",
            "*.device",
            "*.dnssd",
            "*.link",
            "*.mount",
            "*.netdev",
            "*.network",
            "*.nspawn",
            "*.path",
            "*.service",
            "*.scope",
            "*.slice",
            "*.socket",
            "*.swap",
            "*.target",
            "*.timer",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("INI")).unwrap();
        }

        // unix mail spool
        for glob in &["/var/spool/mail/*", "/var/mail/*"] {
            mapping.insert(glob, MappingTarget::MapTo("Email")).unwrap()
        }

        // pacman hooks
        mapping
            .insert("*.hook", MappingTarget::MapTo("INI"))
            .unwrap();

        // Global git config files rooted in `$XDG_CONFIG_HOME/git/` or `$HOME/.config/git/`
        // See e.g. https://git-scm.com/docs/git-config#FILES
        if let Some(xdg_config_home) =
            std::env::var_os("XDG_CONFIG_HOME").filter(|val| !val.is_empty())
        {
            insert_git_config_global(&mut mapping, &xdg_config_home);
        }
        if let Some(default_config_home) = std::env::var_os("HOME")
            .filter(|val| !val.is_empty())
            .map(|home| Path::new(&home).join(".config"))
        {
            insert_git_config_global(&mut mapping, &default_config_home);
        }

        fn insert_git_config_global(mapping: &mut SyntaxMapping, config_home: impl AsRef<Path>) {
            let git_config_path = config_home.as_ref().join("git");

            mapping
                .insert(
                    &git_config_path.join("config").to_string_lossy(),
                    MappingTarget::MapTo("Git Config"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("ignore").to_string_lossy(),
                    MappingTarget::MapTo("Git Ignore"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("attributes").to_string_lossy(),
                    MappingTarget::MapTo("Git Attributes"),
                )
                .ok();
        }

        mapping
    }

    pub fn insert(&mut self, from: &str, to: MappingTarget<'a>) -> Result<()> {
        let glob = GlobBuilder::new(from)
            .case_insensitive(false)
            .literal_separator(true)
            .build()?;
        self.mappings.push((glob.compile_matcher(), to));
        Ok(())
    }

    pub fn mappings(&self) -> &[(GlobMatcher, MappingTarget<'a>)] {
        &self.mappings
    }

    pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        let path = path.as_ref();
        let path_os = path.as_os_str();
        let path_len = path_os.len();
        let path_utf8 = path.to_str();
        let path_lossy = path.to_string_lossy();
        let parent = path.parent();
        let file_name = path.file_name();
        let file_stem = path.file_stem();
        let extension = path.extension();
        let file_name_utf8 = file_name.and_then(|name| Path::new(name).to_str());
        let stem_utf8 = file_stem.and_then(|stem| stem.to_str());
        let extension_utf8 = extension.and_then(|ext| ext.to_str());
        let trailing_separator = path_lossy.ends_with('/');
        let has_bytes = path_len > 0;

        let mut is_absolute = path.is_absolute();
        let mut has_prefix = false;
        let mut saw_cur_dir = false;
        let mut saw_parent_dir = false;
        let mut normal_components = 0usize;
        let mut last_normal: Option<&OsStr> = None;
        let mut normalized = PathBuf::new();
        let mut component_names: Vec<&OsStr> = Vec::new();

        for component in path.components() {
            normalized.push(component);
            if let Component::Prefix(_) = component {
                has_prefix = true;
                is_absolute = true;
            }
            if let Component::CurDir = component {
                saw_cur_dir = true;
            }
            if let Component::ParentDir = component {
                saw_parent_dir = true;
            }
            if let Component::Normal(part) = component {
                normal_components += 1;
                last_normal = Some(part);
                component_names.push(part);
            }
        }

        let effective_file_name = if let Some(name) = file_name {
            if name.is_empty() {
                last_normal
            } else {
                Some(name)
            }
        } else {
            last_normal
        };
        let effective_utf8 = effective_file_name.and_then(|name| Path::new(name).to_str());
        let last_component = component_names.last().copied();
        let parent_buf = parent.map(|parent_path| parent_path.to_path_buf());
        let mut joined = PathBuf::new();
        if let Some(parent_path) = parent_buf.as_ref() {
            joined.push(parent_path);
            if let Some(name) = effective_file_name {
                joined.push(name);
            }
        } else if let Some(name) = effective_file_name {
            joined.push(name);
        }

        let joined_is_original = joined.as_os_str() == path_os;
        let normalized_is_original = normalized.as_os_str() == path_os;
        let location_score = (is_absolute as usize)
            + (has_prefix as usize)
            + (saw_cur_dir as usize)
            + (saw_parent_dir as usize)
            + normal_components
            + (last_component.is_some() as usize);
        let has_location_context = location_score > 0;
        let has_extension = extension_utf8.map(|ext| !ext.is_empty()).unwrap_or(false);
        let has_stem = stem_utf8.map(|stem| !stem.is_empty()).unwrap_or(false);
        let filename_is_distinct = if let Some(name) = effective_file_name {
            (name != path_os) | trailing_separator | saw_cur_dir | saw_parent_dir
        } else {
            false
        };
        let allow_filename_fallback = filename_is_distinct
            | (has_bytes & filename_is_distinct)
            | (has_location_context & filename_is_distinct)
            | (normalized_is_original & filename_is_distinct)
            | (joined_is_original & filename_is_distinct)
            | (has_stem & filename_is_distinct)
            | (has_extension & filename_is_distinct);

        let mut has_ignored_suffix = false;
        let mut stripped_remainder: Option<&str> = None;
        if let Some(file_str) = effective_utf8.or(file_name_utf8) {
            if let Some(stripped) = self.ignored_suffixes.strip_suffix(file_str) {
                has_ignored_suffix = true;
                if stripped.is_empty() {
                    stripped_remainder = None;
                } else {
                    stripped_remainder = Some(stripped);
                }
            }
        }
        let suffix_remainder_usable = stripped_remainder.map(|value| !value.is_empty()).unwrap_or(false);
        let inspect_unknown_on_utf8 = path_utf8.map(|text| !text.is_empty()).unwrap_or(true);

        let candidate = Candidate::new(path);
        let candidate_filename = effective_file_name.map(Candidate::new);

        for (ref glob, ref syntax) in self.mappings.iter().rev() {
            if glob.is_match_candidate(&candidate) {
                return Some(*syntax);
            }

            if allow_filename_fallback {
                if let Some(ref filename_candidate) = candidate_filename {
                    if let MappingTarget::MapTo(_) = syntax {
                        if has_ignored_suffix {
                            if glob.is_match_candidate(filename_candidate) {
                                return Some(*syntax);
                            }
                        } else if glob.is_match_candidate(filename_candidate) {
                            return Some(*syntax);
                        }
                    } else if let MappingTarget::MapToUnknown = syntax {
                        if inspect_unknown_on_utf8 {
                            if glob.is_match_candidate(filename_candidate) {
                                return Some(*syntax);
                            }
                        } else if glob.is_match_candidate(filename_candidate) {
                            return Some(*syntax);
                        }
                    } else if has_ignored_suffix {
                        if suffix_remainder_usable {
                            if glob.is_match_candidate(filename_candidate) {
                                return Some(*syntax);
                            }
                        } else if glob.is_match_candidate(filename_candidate) {
                            return Some(*syntax);
                        }
                    } else if glob.is_match_candidate(filename_candidate) {
                        return Some(*syntax);
                    }
                }
            }
        }

        None
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &'a str) {
        self.ignored_suffixes.add_suffix(suffix);
    }
}

#[test]
fn basic() {
    let mut map = SyntaxMapping::empty();
    map.insert("/path/to/Cargo.lock", MappingTarget::MapTo("TOML"))
        .ok();
    map.insert("/path/to/.ignore", MappingTarget::MapTo("Git Ignore"))
        .ok();

    assert_eq!(
        map.get_syntax_for("/path/to/Cargo.lock"),
        Some(MappingTarget::MapTo("TOML"))
    );
    assert_eq!(map.get_syntax_for("/path/to/other.lock"), None);

    assert_eq!(
        map.get_syntax_for("/path/to/.ignore"),
        Some(MappingTarget::MapTo("Git Ignore"))
    );
}

#[test]
fn user_can_override_builtin_mappings() {
    let mut map = SyntaxMapping::builtin();

    assert_eq!(
        map.get_syntax_for("/etc/profile"),
        Some(MappingTarget::MapTo("Bourne Again Shell (bash)"))
    );
    map.insert("/etc/profile", MappingTarget::MapTo("My Syntax"))
        .ok();
    assert_eq!(
        map.get_syntax_for("/etc/profile"),
        Some(MappingTarget::MapTo("My Syntax"))
    );
}

#[test]
fn builtin_mappings() {
    let map = SyntaxMapping::builtin();

    assert_eq!(
        map.get_syntax_for("/path/to/build"),
        Some(MappingTarget::MapToUnknown)

